<template>
<section class="national-alarm-popup" :style="style" role="dialog" aria-modal="false" aria-label="浙江预警详情" @click.stop><header><strong>{{ alarm.title || '--' }}</strong><button type="button" aria-label="关闭预警浮窗" @click="emit('close')">×</button></header><div><p>发布时间：{{ formatNationalAlarmTime(alarm.issuedAt) }}</p><p class="body">{{ detail?.phase==='ready' ? (detail.body || '预警正文暂不可用') : detail?.phase==='loading' ? '正在读取官方预警正文…' : '预警正文暂不可用' }}</p><button v-if="detail?.phase==='error'&&detail.retryAvailable" type="button" class="retry" @click="emit('retry')">重试</button><small>官方预警正文</small></div></section>
</template>
<script setup lang="ts">
import {computed} from 'vue';import type {NationalAlarmDetailState,NationalWeatherAlarm} from '../../features/national-alarms/nationalAlarmTypes';import {formatNationalAlarmTime} from '../../features/national-alarms/nationalAlarmSelectors';const props=defineProps<{alarm:NationalWeatherAlarm;detail:NationalAlarmDetailState|null;x:number;y:number}>();const emit=defineEmits<{close:[];retry:[]}>();const style=computed(()=>{const width=360,height=360,pad=12,gap=18;const left=Math.max(pad,Math.min(props.x-width/2,window.innerWidth-pad-width));const above=props.y-height-gap>=pad;const top=above?props.y-height-gap:Math.min(window.innerHeight-pad-height,props.y+gap);return{left:`${left}px`,top:`${Math.max(pad,top)}px`}});
</script>
<style scoped>.national-alarm-popup{position:fixed;z-index:1040;width:360px;max-height:calc(100vh - 24px);display:flex;flex-direction:column;border:1px solid rgba(148,163,184,.45);border-radius:10px;background:#fff;box-shadow:0 12px 30px rgba(15,23,42,.25);color:#0f172a}.national-alarm-popup header{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px;padding:8px 10px;border-radius:9px 9px 0 0;background:#2563eb;color:#fff}.national-alarm-popup header strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px;line-height:1.25}.national-alarm-popup header button{border:0;background:transparent;color:inherit;font-size:18px;cursor:pointer}.national-alarm-popup>div{min-height:0;overflow:auto;padding:12px}.national-alarm-popup p{margin:0 0 10px;font-size:12px;line-height:1.6}.national-alarm-popup .body{white-space:pre-wrap}.national-alarm-popup small{color:#64748b;font-size:11px}.retry{height:30px;margin-bottom:10px;border:0;border-radius:6px;background:#2563eb;color:#fff;cursor:pointer}@media(max-width:520px){.national-alarm-popup{width:calc(100vw - 24px)}}</style>
